      const fOverSpace = hoodEndZ - fClearMax - 0.14;
      const frontDoorZ = fOverSpace >= doorW + 0.1
        ? fClearMax + 0.1 + doorW * 0.5
        : clamp(fClearMin - doorW * 0.5 - 0.08, rClearMax + doorW * 0.5 + 0.08, fClearMin - doorW * 0.5 - 0.04);
